candidates.raw:
    if (current == NULL || target == NULL || required_rate == NULL || margin == NULL) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_NULL;
    }

    if (!isfinite(max_rate) || !isfinite(duration) || duration <= 0.0) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_quat_t norm_current, norm_target;
    if (adcs_quat_normalize(current, &norm_current) != ADCS_OK) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }
    if (adcs_quat_normalize(target, &norm_target) != ADCS_OK) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }

    adcs_quat_t conj_current = adcs_quat_conjugate(&norm_current);
    adcs_quat_t q_rel = adcs_quat_multiply(&norm_target, &conj_current);

    double abs_w = fabs(q_rel.w);
    double clamped_w = ADCS_CLAMP(abs_w, 0.0, 1.0);
    double angle = 2.0 * acos(clamped_w);

    double required_rate_val = angle / duration;
    double margin_val = max_rate - required_rate_val;

    *required_rate = required_rate_val;
    *margin = margin_val;

    return ADCS_OK;
}

